// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title MessageQueueConsumer
 * @notice Processes messages from off-chain relay infrastructure
 * @dev Designed to sit behind a reverse proxy that authenticates upstream connections
 *      using NTLM-style challenge-response before forwarding signed messages on-chain.
 *      The proxy attests message origin by including its own signature wrapper.
 */
contract MessageQueueConsumer {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct RelayedMessage {
        address sender;
        address target;
        bytes payload;
        uint256 nonce;
        uint256 deadline;
        bytes32 channelId;
    }

    struct ProxyAttestation {
        bytes32 sessionHash;    // NTLM session key hash from proxy auth
        uint256 timestamp;
        bytes proxySignature;   // Proxy's ECDSA sig over (messageHash, sessionHash)
    }

    address public immutable trustedProxy;
    address public owner;

    mapping(bytes32 => bool) public processedMessages;
    mapping(bytes32 => uint256) public channelNonces;
    mapping(address => bool) public authorizedRelayers;
    mapping(bytes32 => address) public sessionBindings;
    mapping(address => bytes32) public senderToSession;

    event MessageProcessed(bytes32 indexed messageId, address indexed sender, address target);
    event SessionBound(bytes32 indexed sessionHash, address indexed relayer);
    event RelayerAuthorized(address indexed relayer);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor(address _trustedProxy) {
        require(_trustedProxy != address(0), "Zero proxy address");
        trustedProxy = _trustedProxy;
        owner = msg.sender;
    }

    function authorizeRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = true;
        emit RelayerAuthorized(relayer);
    }

    /**
     * @notice Bind an NTLM session to a relayer address
     * @dev Called by proxy after successful NTLM authentication
     */
    function bindSession(bytes32 sessionHash, address relayer, bytes calldata proxySignature) external {
        bytes32 bindingHash = keccak256(abi.encodePacked(sessionHash, relayer, block.chainid));
        bytes32 ethSignedHash = bindingHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(proxySignature);

        require(recovered == trustedProxy, "Invalid proxy signature");
        require(authorizedRelayers[relayer], "Relayer not authorized");

        sessionBindings[sessionHash] = relayer;
        emit SessionBound(sessionHash, relayer);
    }

    /**
     * @notice Process a relayed message with proxy attestation
     * @dev Validates the full authentication chain: NTLM session -> proxy attestation -> message
     */
    function processMessage(
        RelayedMessage calldata message,
        ProxyAttestation calldata attestation,
        bytes calldata senderSignature
    ) external returns (bool) {
        // Step 1: Verify deadline
        require(block.timestamp <= message.deadline, "Message expired");

        // Step 2: Compute message hash
        bytes32 messageHash = _computeMessageHash(message);

        // Step 3: Check replay protection
        require(!processedMessages[messageHash], "Already processed");

        // Step 4: Verify nonce ordering per channel
        require(message.nonce == channelNonces[message.channelId], "Invalid nonce");

        // Step 5: Validate proxy attestation
        _validateProxyAttestation(messageHash, attestation);

        // Step 6: Validate sender signature
        _validateSenderSignature(messageHash, message.sender, senderSignature);

        // Step 7: Verify session binding matches sender's authorized relayer
        _validateSessionBinding(attestation.sessionHash, message.sender);

        // Step 8: Execute
        processedMessages[messageHash] = true;
        channelNonces[message.channelId]++;

        (bool success,) = message.target.call(message.payload);

        emit MessageProcessed(messageHash, message.sender, message.target);
        return success;
    }

    function _computeMessageHash(RelayedMessage calldata message) internal view returns (bytes32) {
        return keccak256(abi.encode(
            message.sender,
            message.target,
            keccak256(message.payload),
            message.nonce,
            message.deadline,
            message.channelId,
            block.chainid,
            address(this)
        ));
    }

    function _validateProxyAttestation(
        bytes32 messageHash,
        ProxyAttestation calldata attestation
    ) internal view {
        require(
            block.timestamp - attestation.timestamp <= 300,
            "Attestation too old"
        );

        bytes32 attestationHash = keccak256(abi.encodePacked(
            messageHash,
            attestation.sessionHash,
            attestation.timestamp
        ));
        bytes32 ethSignedHash = attestationHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(attestation.proxySignature);

        require(recovered == trustedProxy, "Invalid proxy attestation");
    }

    function _validateSenderSignature(
        bytes32 messageHash,
        address sender,
        bytes calldata signature
    ) internal pure {
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);
        require(recovered == sender, "Invalid sender signature");
    }

    /**
     * @notice Validates that the session is bound to an authorized relayer for this sender
     * @dev The session binding ensures NTLM-authenticated identity matches the relay path
     *      Each sender must be explicitly associated with a specific session
     */
    function _validateSessionBinding(
        bytes32 sessionHash,
        address sender
    ) internal view {
        address boundRelayer = sessionBindings[sessionHash];
        // Verify session is bound to an authorized relayer
        require(boundRelayer != address(0), "Session not bound");
        // Verify this specific sender is authorized to use this session's relayer
        require(senderToSession[sender] == sessionHash, "Sender not bound to session");
    }

    /**
     * @notice Bind a sender to a specific session (called by owner after KYC)
     */
    function bindSenderToSession(address sender, bytes32 sessionHash) external onlyOwner {
        require(sessionBindings[sessionHash] != address(0), "Session not established");
        senderToSession[sender] = sessionHash;
    }

    /**
     * @notice Emergency: revoke a compromised session
     */
    function revokeSession(bytes32 sessionHash) external onlyOwner {
        delete sessionBindings[sessionHash];
    }
}
